gold.schema_ddl:
CREATE TABLE classificazione_prodotti (
    id SERIAL PRIMARY KEY,
    nome_categoria TEXT NOT NULL UNIQUE,
    descrizione TEXT
);

CREATE TABLE vendite (
    id SERIAL PRIMARY KEY,
    classificazione_prodotto_id INT NOT NULL REFERENCES classificazione_prodotti(id),
    quantita_venduta INT NOT NULL CHECK (quantita_venduta >= 0),
    prezzo_unitario NUMERIC(10,2) CHECK (prezzo_unitario >= 0),
    importo_totale NUMERIC(10,2) CHECK (importo_totale >= 0),
    data_vendita DATE NOT NULL
);
